nested-three:
namespace ThreeOuter {
    namespace ThreeMiddle {
        namespace ThreeInner {}
    }
}

nested-siblings:
namespace SiblingOuter {
    namespace First {}
    namespace Second {}
}

keyword-line-and-case:
namespace KeywordOuter {
    // The child keyword, not its name or brace, owns the location.
    NaMeSpAcE
    KeywordInner
    {
    }
}

body-parameter:
namespace ParameterOuter {
    namespace ParameterInner {
        function bad(void $value) {}
    }
}

body-hook:
namespace HookOuter {
    namespace HookInner {
        class C { public int $p { MeOw => 1; } }
    }
}

outer-body-parameter:
namespace OuterParameter {
    namespace InnerParameter {}
    function bad(void $value) {}
}

earlier-name:
namespace EarlierNameOuter {
    #[\self] class C {}
    namespace EarlierNameInner {}
}

same-file-rules:
namespace RuleOuter {
    missing_before_namespace();
    namespace RuleInner { missing_inside_namespace(); }
    missing_after_namespace();
}
